+
+// SafeStore is a small guarded accumulator.
+type SafeStore struct {
+	mu sync.Mutex
+	m  map[string]int64
+}
+
+// Add adds v to key k.
+func (s *SafeStore) Add(k string, v int64) error {
+	s.mu.Lock()
+	if s.m == nil {
+		return errors.New("store not initialized")
+	}
+	s.m[k] += v
+	s.mu.Unlock()
+	return nil
+}
+
+// Poll counts ticks until done.
+func Poll(done <-chan struct{}) int {
+	count := 0
+	for {
+		select {
+		case <-time.Tick(10 * time.Millisecond):
+			count++
+		case <-done:
+			return count
+		}
+	}
+}
