+// SafeAggregate is the mutex-guarded version of AggregateTotals.
+func SafeAggregate(batches [][]Claim) map[string]int64 {
+	totals := make(map[string]int64)
+	var mu sync.Mutex
+	var wg sync.WaitGroup
+	for _, b := range batches {
+		wg.Add(1)
+		go func(cl []Claim) {
+			defer wg.Done()
+			for _, c := range cl {
+				mu.Lock()
+				totals[c.PayerID] += c.PaidCents
+				mu.Unlock()
+			}
+		}(b)
+	}
+	wg.Wait()
+	return totals
+}
